export function getTranslatedLiuGongSparePartName(name: string, language: string = 'zh'): string {
  const translations = liugongNameTranslations[name];
  if (translations && translations[language]) {
    return translations[language];
  }
  return name;
}

export function getTranslatedLiuGongSparePartCategory(category: string, language: string = 'zh'): string {
  const translations = liugongCategoryTranslations[category];
  if (translations && translations[language]) {
    return translations[language];
  }
  return category;
}

export function getTranslatedLiuGongSparePartDescription(description: string, language: string = 'zh'): string {
  const translations = liugongDescriptionTranslations[description];
  if (translations && translations[language]) {
    return translations[language];
  }
  return description;
}


